package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="SOSEvent") public class SOSEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer sosId; @ManyToOne @JoinColumn(name="user_id") private User user; @ManyToOne @JoinColumn(name="trip_id") private Trip trip; private BigDecimal latitude,longitude; @Enumerated(EnumType.STRING) private SosStatus sosStatus; private LocalDateTime createdAt; public enum SosStatus{Active,Resolved,Cancelled} public SOSEvent(){} public Integer getSosId(){return sosId;} public void setSosId(Integer v){sosId=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public Trip getTrip(){return trip;} public void setTrip(Trip v){trip=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public SosStatus getSosStatus(){return sosStatus;} public void setSosStatus(SosStatus v){sosStatus=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
